pm.test("Status 201 Created", () => {
  pm.response.to.have.status(201);
});

pm.test("Sifarişin sxemi düzgündür", () => {
  const body = pm.response.json();
  pm.expect(body.id).to.be.a("number");
  pm.expect(body.status).to.eql("pending");
  pm.expect(body.currency).to.eql("AZN");
});

// Növbəti request-də istifadə etmək üçün id-ni saxla
pm.environment.set("orderId", pm.response.json().id);

-- Bütün sütunlar
SELECT * FROM users;

-- Yalnız lazım olan sütunlar
SELECT id, email, status FROM users;

-- Şərtlə: bloklanmış istifadəçilər
SELECT id, email FROM users WHERE status = 'blocked';

-- Bir neçə şərt
SELECT * FROM orders WHERE status = 'paid' AND total > 30;

-- Şəhəri boş qalan istifadəçilər
SELECT id, email FROM users WHERE city IS NULL;

-- Ən son 5 sifariş
SELECT * FROM orders ORDER BY created_at DESC LIMIT 5;

-- Neçə aktiv istifadəçi var?
SELECT COUNT(*) FROM users WHERE status = 'active';

-- Hər statusda neçə sifariş var?
SELECT status, COUNT(*) AS order_count
FROM orders
GROUP BY status;

SELECT id, full_name, email, city, status, password_hash
FROM users
WHERE email = 'elvin.q@narix.az';
